        c = i < length ? js_pi_script_code_unit(source, i) : 0;
        if (i != length && c != '\n' && c != CP_LS && c != CP_PS &&
            !(c == '\r' && (i + 1 == length ||
              js_pi_script_code_unit(source, i + 1) != '\n')))
            continue;
        if (position <= i) {
            result.line = line;
            result.column = position - start;
            result.line_start = start;
            result.line_end = i;
